document.addEventListener('click',e=>{
  let folder=e.target.closest('[data-board-folder]'),toggle=e.target.closest('[data-board-folder-toggle]'),favorite=e.target.closest('[data-board-favorite]');
  if(e.target.closest('[data-board-more]')){boardLimit+=60;render();return}
  if(toggle){let id=toggle.dataset.boardFolderToggle;if(collapsedBoardFolders.has(id))collapsedBoardFolders.delete(id);else collapsedBoardFolders.add(id);render();return}
  if(folder){selectedBoardFolder=folder.dataset.boardFolder;boardQuery='';boardLimit=60;render();return}
  if(favorite){let board=items('blackboards').find(b=>b.id===favorite.dataset.boardFavorite);if(board){board.favorite=!board.favorite;save();render()}return}
  let action=e.target.closest('[data-action]'),edit=e.target.closest('[data-edit-board]');if(action?.dataset.action==='boardFolder'){$('#boardParentFolder').innerHTML='<option value="">最上位</option>'+boardFolders().map(f=>`<option value="${esc(f.id)}" ${selectedBoardFolder===f.id?'selected':''}>${esc(boardFolderPath(f))}</option>`).join('')}
  if(formType==='board'&&(action?.dataset.action==='board'||edit)){let board=edit?items('blackboards').find(b=>b.id===edit.dataset.editBoard):null;$('#boardFolderSelect').innerHTML='<option value="">未分類</option>'+boardFolders().map(f=>`<option value="${esc(f.id)}" ${(board?.folderId||(!edit&&selectedBoardFolder!=='all'&&selectedBoardFolder!=='none'?selectedBoardFolder:''))===f.id?'selected':''}>${esc(boardFolderPath(f))}</option>`).join('')}
});
