function renderSchedule(){
  const ss=items('schedule').sort((a,b)=>(a.start||a.date).localeCompare(b.start||b.date));
  const config=scheduleSettings(),dates=scheduleDates(config.start,scheduleDays(config.type));
  const types=['週間工程表','月間工程表','2ヶ月工程','3ヶ月工程','半年工程表','1年工程表'],papers=['A3横','A3縦','A1','A4'];
  const lines=scheduleLines(),editing=lines.find(x=>x.id===editingScheduleLineId);
  const options=(values,chosen)=>values.map(([value,label])=>`<option value="${value}" ${chosen===value?'selected':''}>${label}</option>`).join('');
  const task=editing?.taskId||ss[0]?.id||'';
  const start=editing?.start||dates[0],end=editing?.end||dates[Math.min(6,dates.length-1)];
  const toolbar=`<section class="card schedule-toolbar"><div class="toolbar"><label>工程表<select id="scheduleType">${types.map(x=>`<option ${config.type===x?'selected':''}>${x}</option>`).join('')}</select></label><label>用紙サイズ<select id="schedulePaper">${papers.map(x=>`<option ${config.paper===x?'selected':''}>${x}</option>`).join('')}</select></label><label>表示開始日<input type="date" id="scheduleStart" value="${esc(config.start)}"></label><button type="button" class="btn ${config.todayStart?'':'secondary'}" data-schedule-today-start aria-pressed="${!!config.todayStart}" title="オン：今日から表示／オフ：表示月の1日から表示">${config.todayStart?'今日から表示中 · 月初に戻す':'今日から表示'}</button><button class="btn secondary" data-schedule-export>Excelダウンロード（.xlsx）</button></div><p class="hint">表示期間：${esc(dates[0])} ～ ${esc(dates.at(-1))}。工程行の日付を2回押すと線の開始日と終了日を指定できます。</p></section>`;
  const tools=config.lineTools||{};
  const selected=editing||tools;
  const lineEditor=`<section class="card schedule-addin-toolbar" id="scheduleLineEditor" aria-label="工程線ツールバー"><form id="scheduleLineForm">
    <input type="hidden" name="taskId" value="${esc(task)}"><input type="hidden" name="start" value="${esc(start)}"><input type="hidden" name="end" value="${esc(end)}">
    <label>線種<select name="style">${options([['solid','━ 実線'],['dashed','┄ 破線'],['dotted','┈ 点線'],['r-right-up','┛ R線'],['r-right-down','┓ R線'],['r-left-up','┗ R線'],['r-left-down','┏ R線']],selected.style||'solid')}</select></label>
    <label>太さ<select name="weight">${options([['1','細い'],['2','標準'],['3','太い']],String(selected.weight||2))}</select></label>
    <label>色<input type="color" name="color" value="${/^#[0-9a-f]{6}$/i.test(selected.color)?selected.color:'#304960'}"></label>
    <div class="schedule-color-palette" role="group" aria-label="基本色">${[['#000000','黒'],['#ff0000','赤'],['#0000ff','青'],['#ffff00','黄'],['#00ff00','緑'],['#00ffff','水色'],['#ff00ff','紫紅'],['#ffffff','白'],['#ff8000','橙'],['#800080','紫'],['#808080','灰']].map(([color,name])=>`<button type="button" data-grid-color="${color}" style="--swatch:${color}" aria-label="${name}" title="${name}"></button>`).join('')}</div>
    <label>始点<select name="startMarker">${options([['none','なし'],['open','○ 白丸'],['filled','● 黒丸'],['arrow','← 矢印']],selected.startMarker||'none')}</select></label>
    <label>終点<select name="endMarker">${options([['none','なし'],['open','○ 白丸'],['filled','● 黒丸'],['arrow','→ 矢印']],selected.endMarker||'none')}</select></label>
    <label class="schedule-tool-label">文字<input name="label" maxlength="80" placeholder="例：足場組立" value="${esc(selected.label||'')}"></label>
    <div class="schedule-alignment-tools" role="group" aria-label="文字の配置"><button type="button" data-grid-align="left" aria-label="左寄せ" title="左寄せ">左寄せ</button><button type="button" data-grid-align="center" aria-label="中央配置" title="中央配置">中央</button><button type="button" data-grid-align="right" aria-label="右寄せ" title="右寄せ">右寄せ</button></div>
    <div class="schedule-tool-buttons"><button class="btn" type="${editing?'submit':'button'}" ${editing?'':'data-grid-draw'}>${editing?'変更を保存':'線を引く'}</button><button class="btn secondary" type="button" data-grid-clear>選択解除</button>${editing?'<button type="button" class="btn secondary" data-schedule-line-cancel>編集をやめる</button>':''}</div>
    </form><span id="schedulePickStatus" role="status" class="hint"></span></section>`;
  const dayHeader=dates.map(d=>`<th class="${new Date(d+'T12:00:00').getDay()===0?'holiday':''}">${esc(d.slice(5))}<small>${'日月火水木金土'[new Date(d+'T12:00:00').getDay()]}</small></th>`).join('');
  const body=ss.map(s=>{
    const main=`<tr><th class="schedule-sticky"><b>${esc(s.title)}</b><small>${esc(s.note||'')}</small></th>${dates.map(d=>`<td class="${!s.gridOnly&&d>=(s.start||s.date)&&d<=(s.end||s.start||s.date)?'scheduled':''} ${new Date(d+'T12:00:00').getDay()===0?'holiday':''}"><button type="button" class="schedule-day-pick" data-schedule-pick="${esc(d)}" data-schedule-task="${esc(s.id)}" aria-label="${esc(s.title)} ${esc(d)} を線の日付に指定"></button></td>`).join('')}<td><button class="btn danger" data-delete="schedule:${esc(s.id)}">削除</button></td></tr>`;
    return main+lines.filter(line=>line.taskId===s.id).map(line=>`<tr class="schedule-annotation"><th class="schedule-sticky"><small>${esc(line.label||({solid:'実線',dashed:'破線',dotted:'点線',r:'R線'}[line.style]||'工程線'))}</small><small>${esc(line.start)} ～ ${esc(line.end)}</small></th><td colspan="${dates.length}" class="schedule-track-cell">${scheduleLineTrack(line,dates)}</td><td><div class="schedule-annotation-actions"><button class="btn secondary" data-schedule-line-edit="${esc(line.id)}">編集</button><button class="btn danger" data-schedule-line-delete="${esc(line.id)}">削除</button></div></td></tr>`).join('');
  }).join('')||`<tr><td colspan="${dates.length+2}">工程はまだありません。「工程を追加」から登録してください。</td></tr>`;
  return intro('SCHEDULE','工程管理','日付ごとの工程と工程線を編集し、Excelで書き出せます','工程を追加','schedule')+toolbar+lineEditor+`<section class="card schedule-sheet"><div class="section-head"><div><h2>${esc(config.type)}（${esc(config.paper)}）</h2><p class="hint">${ss.length}工程 · ${lines.length}本の線</p></div></div><div class="schedule-scroll"><table class="schedule-grid"><thead><tr><th class="schedule-sticky">工程・項目</th>${dayHeader}<th>操作</th></tr></thead><tbody>${body}</tbody></table></div></section>`;
}

