  ctx.fillStyle='#075927';ctx.fillRect(bx,by,bw,bh);ctx.lineWidth=Math.max(2,Math.round(w*.002));ctx.strokeStyle='#fff';ctx.strokeRect(bx,by,bw,bh);const font=Math.max(12,Math.round(row*.4));ctx.font=`bold ${font}px sans-serif`;ctx.textBaseline='middle';ctx.fillStyle='#fff';
  function clipped(value,x,y,max){let label=String(value||'');while(label.length&&ctx.measureText(label).width>max)label=label.slice(0,-1);ctx.fillText(label,x,y)}
  fields.forEach((field,i)=>{let y=by+row*i;ctx.beginPath();ctx.moveTo(bx,y+row);ctx.lineTo(bx+bw,y+row);ctx.moveTo(bx+left,y);ctx.lineTo(bx+left,y+row);ctx.stroke();clipped(field.label,bx+8,y+row/2,left-14);clipped(field.value,bx+left+8,y+row/2,bw-left-16)});
  const notesY=by+row*fields.length,footer=board.footer==='date'?row:0;ctx.font=`bold ${Math.max(12,Math.round(font*.9))}px sans-serif`;clipped(board.note||'備考',bx+9,notesY+row/2,bw-18);
  if(board.diagram){try{const diagram=await loadImage(board.diagram),available=Math.max(0,bh-(notesY-by)-footer-row-8);if(available>12){let scale=Math.min((bw-16)/diagram.naturalWidth,available/diagram.naturalHeight);ctx.drawImage(diagram,bx+(bw-diagram.naturalWidth*scale)/2,notesY+row,diagram.naturalWidth*scale,diagram.naturalHeight*scale)}}catch{}}
  if(footer){ctx.beginPath();ctx.moveTo(bx,by+bh-footer);ctx.lineTo(bx+bw,by+bh-footer);ctx.stroke();clipped(photo.date||'',bx+8,by+bh-footer/2,bw*.42);clipped(board.contractor||'施工者',bx+bw*.45,by+bh-footer/2,bw*.5)}
  return new Promise((resolve,reject)=>canvas.toBlob(blob=>blob?resolve(blob):reject(new Error('画像を書き出せませんでした')),'image/jpeg',.9));
