function moveFolderByDrop(kind,sourceId,targetId,zone){const key=kind+'Folders',all=items(key),source=all.find(f=>f.id===sourceId),target=all.find(f=>f.id===targetId);if(!source||!target||source.id===target.id)return false;const parentId=zone==='inside'?target.id:target.parentId||'';let cursor=parentId,visited=new Set();while(cursor&&!visited.has(cursor)){if(cursor===sourceId)return false;visited.add(cursor);cursor=all.find(f=>f.id===cursor)?.parentId}if(all.some(f=>f.id!==source.id&&f.name===source.name&&(f.parentId||'')===parentId)){alert('移動先に同名のフォルダーがあります');return false}const previous=data[key],siblings=sortedFolderList(kind,all.filter(f=>(f.parentId||'')===parentId&&f.id!==source.id)),position=zone==='inside'?siblings.length:siblings.findIndex(f=>f.id===target.id)+(zone==='after'?1:0);siblings.splice(Math.max(0,position),0,source);const order=new Map(siblings.map((f,i)=>[f.id,i])),oldParent=source.parentId||'',oldSiblings=oldParent===parentId?[]:sortedFolderList(kind,all.filter(f=>(f.parentId||'')===oldParent&&f.id!==source.id));oldSiblings.forEach((f,i)=>order.set(f.id,i));data[key]=previous.map(f=>f.projectId===projectId&&order.has(f.id)?{...f,parentId:f.id===source.id?parentId:f.parentId,order:order.get(f.id)}:f);if(!save()){data[key]=previous;return false}render();return true}
