function renameSelectedFolder(kind){const config=kind==='photo'?{key:'photoFolders',id:selectedPhotoFolder}:kind==='board'?{key:'boardFolders',id:selectedBoardFolder}:{key:'ledgerFolders',id:selectedLedgerFolder};const folders=items(config.key),folder=folders.find(f=>f.id===config.id);if(!folder)return;const proposed=prompt('フォルダー名を変更',folder.name);if(proposed===null)return;const name=proposed.trim();if(!name||name.length>50)return alert('フォルダー名を1〜50文字で入力してください');if(name===folder.name)return;if(folders.some(f=>f.id!==folder.id&&f.parentId===folder.parentId&&f.name===name))return alert('同じ階層に同名のフォルダーがあります');const previous=data[config.key];data[config.key]=previous.map(f=>f.id===folder.id?{...f,name}:f);if(!save()){data[config.key]=previous;return}render()}
