async function startPhotoCamera(){if(!navigator.mediaDevices?.getUserMedia){$('#photoCameraStatus').textContent='この端末ではカメラを利用できません。写真ファイルから登録してください。';return}stopPhotoCamera();const request=photoCameraRequest;try{let stream=await navigator.mediaDevices.getUserMedia({audio:false,video:{facingMode:{ideal:'environment'}}});if(request!==photoCameraRequest||formType!=='photo'||$('#modal').hidden){stream.getTracks().forEach(track=>track.stop());return}photoCameraStream=stream;let video=$('#photoCameraVideo');video.srcObject=stream;video.hidden=false;$('#photoCameraStill').hidden=true;$('#photoCameraStage').hidden=false;$('[data-camera-capture]').hidden=false;$('[data-camera-stop]').hidden=false;$('#photoCameraStatus').textContent=$('#boardSelect')?.value?'黒板を画面上に表示中。撮影後も黒板付きで確認できます。':'黒板なしで撮影します。';await video.play();syncMobileCameraHud()}catch(err){if(request===photoCameraRequest){stopPhotoCamera();$('#photoCameraStatus').textContent='カメラを開けませんでした。カメラを許可するか、写真を選択してください。';syncMobileCameraHud()}}}
