document.addEventListener('click',async e=>{let button=e.target.closest('[data-camera-start],[data-camera-stop],[data-camera-capture]');if(!button)return;if(button.hasAttribute('data-camera-stop')){stopPhotoCamera();$('#photoCameraStage').hidden=true;$('#photoCameraStatus').textContent='カメラを閉じました';return}if(button.hasAttribute('data-camera-start')){await startPhotoCamera();return}if(button.hasAttribute('data-camera-capture')){let video=$('#photoCameraVideo');if(!video.videoWidth){$('#photoCameraStatus').textContent='カメラの準備ができてから撮影してください。';return}let canvas=document.createElement('canvas'),stage=$('#photoCameraStage'),viewRatio=mobileCaptureFlow&&stage.clientWidth&&stage.clientHeight?stage.clientWidth/stage.clientHeight:video.videoWidth/video.videoHeight,cropWidth=Math.min(video.videoWidth,video.videoHeight*viewRatio),cropHeight=Math.min(video.videoHeight,video.videoWidth/viewRatio),scale=Math.min(1,1200/Math.max(cropWidth,cropHeight));canvas.width=Math.max(1,Math.round(cropWidth*scale));canvas.height=Math.max(1,Math.round(cropHeight*scale));canvas.getContext('2d').drawImage(video,(video.videoWidth-cropWidth)/2,(video.videoHeight-cropHeight)/2,cropWidth,cropHeight,0,0,canvas.width,canvas.height);capturedPhotoData=canvas.toDataURL('image/jpeg',.72);if(mobileCaptureFlow)$('#entryForm button[type=submit]').disabled=false;let still=$('#photoCameraStill');still.src=capturedPhotoData;still.hidden=false;video.hidden=true;stopPhotoCamera();$('#entryForm [name=file]').value='';$('#photoCameraStatus').textContent='撮影できました。保存するか、撮り直してください。';syncMobileCameraHud()}});

function boardMoveOptions(except=''){let folders=boardFolders(),available=folders.filter(f=>!except||!boardInFolder(f.id,except)),seen=new Set(),ordered=[];function append(parentId,depth){for(let folder of available.filter(f=>f.parentId===parentId)){if(seen.has(folder.id))continue;seen.add(folder.id);ordered.push({folder,depth});append(folder.id,depth+1)}}append('',0);for(let folder of available){if(!seen.has(folder.id))append(folder.parentId,0)}return '<option value="" disabled selected>移動先を選択</option><option value="root">最上位・未分類</option>'+ordered.map(({folder,depth})=>`<option value="${esc(folder.id)}">${'　'.repeat(Math.min(depth,8))}${depth?'↳ ':''}${esc(boardFolderPath(folder).replaceAll(' / ',' › '))}</option>`).join('')}
