document.addEventListener('click',e=>{let button=e.target.closest('[data-mobile-shutter],[data-mobile-retake],[data-mobile-save],[data-mobile-options],[data-mobile-close]');if(!button||!mobileCaptureFlow||formType!=='photo')return;if(button.hasAttribute('data-mobile-close')){closeForm();return}if(button.hasAttribute('data-mobile-options')){$('#mobileCameraExtras').hidden=!$('#mobileCameraExtras').hidden;return}if(button.hasAttribute('data-mobile-shutter')){if(!button.disabled)$('[data-camera-capture]').click();return}if(button.hasAttribute('data-mobile-retake')){capturedPhotoData='';clearMobileFilePreview();$('#entryForm [name=file]').value='';$('#photoCameraStill').hidden=true;$('#photoCameraStage').hidden=true;$('#entryForm button[type=submit]').disabled=true;$('#mobileCameraExtras').hidden=true;syncMobileCameraHud();startPhotoCamera();return}if(button.hasAttribute('data-mobile-save')&&!button.disabled){$('#entryForm').requestSubmit($('#entryForm button[type=submit]'))}});

fields.companyProfile={title:'会社情報を登録・編集',html:'<label class="field">会社名<input name="name" required maxlength="100" placeholder="例：株式会社ダイトク"></label><label class="field">連絡先・メモ<input name="contact" maxlength="120" placeholder="会社の代表連絡先など"></label>'};
fields.userProfile={title:'ユーザー情報を登録',html:'<label class="field">氏名<input name="name" required maxlength="80"></label><label class="field">所属会社・協力会社<input name="affiliation" maxlength="100"></label><label class="field">メール<input type="email" name="email" maxlength="120"></label><label class="field">電話<input type="tel" name="phone" maxlength="40"></label><label class="field">役割<select name="role"><option>会社管理者</option><option>現場管理者</option><option selected>担当者</option><option>閲覧者</option></select></label><fieldset class="user-site-choices"><legend>所属現場と階層（複数選択可）</legend><div id="userProjectChoices"></div></fieldset><p class="hint">役割は現在、担当を整理するための表示項目です。</p>'};
let editingUserId='';
function openUserProfile(id=''){let user=data.users.find(u=>u.id===id);editingUserId=user?.id||'';openForm('userProfile');$('#modalTitle').textContent=user?'ユーザー情報を編集':'ユーザー情報を登録';if(user)for(let key of ['name','affiliation','email','phone','role'])$(`#entryForm [name=${key}]`).value=user[key]||'';$('#userProjectChoices').innerHTML=data.projects.length?data.projects.map(p=>`<div class="user-project-entry"><label><input type="checkbox" name="projectId" value="${esc(p.id)}" ${(user?.projectIds||[]).includes(p.id)?'checked':''}> ${esc(p.name)}</label><div class="user-role-options">${['現場管理者','担当者','閲覧者'].map(role=>`<label><input type="checkbox" name="siteRole:${esc(p.id)}" value="${role}" ${(user?.siteRoles?.[p.id]||((user?.projectIds||[]).includes(p.id)?[user?.role==='会社管理者'?'現場管理者':user?.role||'担当者']:[])).includes(role)?'checked':''}> ${role}</label>`).join('')}</div></div>`).join(''):'<p class="hint">現場がまだありません。現場管理から先に登録できます。</p>'}
$('#profileButton').addEventListener('click',()=>{page='users';render()});
document.addEventListener('click',e=>{let el=e.target.closest('[data-company-edit],[data-user-add],[data-user-edit],[data-user-delete],[data-user-active]');if(!el)return;if(el.hasAttribute('data-company-edit')){openForm('companyProfile');$('#entryForm [name=name]').value=data.companyProfile.name||'';$('#entryForm [name=contact]').value=data.companyProfile.contact||'';return}if(el.hasAttribute('data-user-add')){openUserProfile();return}if(el.hasAttribute('data-user-edit')){openUserProfile(el.dataset.userEdit);return}if(el.hasAttribute('data-user-active')){let user=data.users.find(u=>u.id===el.dataset.userActive);if(!user)return;let old=data.activeUserId;data.activeUserId=user.id;if(!save()){data.activeUserId=old;return}render();return}if(el.hasAttribute('data-user-delete')){let user=data.users.find(u=>u.id===el.dataset.userDelete);if(!user||!confirm(`「${user.name}」のユーザー情報を削除しますか？`))return;let old=data.users,oldActive=data.activeUserId;data.users=old.filter(u=>u.id!==user.id);if(data.activeUserId===user.id)data.activeUserId='';if(!save()){data.users=old;data.activeUserId=oldActive;return}render()}});
$('#entryForm').addEventListener('submit',e=>{if(formType!=='companyProfile'&&formType!=='userProfile')return;e.preventDefault();e.stopImmediatePropagation();let f=new FormData(e.currentTarget);if(formType==='companyProfile'){let name=String(f.get('name')||'').trim();if(!name)return alert('会社名を入力してください');let old=data.companyProfile;data.companyProfile={name,contact:String(f.get('contact')||'').trim()};if(!save()){data.companyProfile=old;return}}else{let name=String(f.get('name')||'').trim(),role=String(f.get('role')||'担当者'),projectIds=f.getAll('projectId').map(String).filter(id=>data.projects.some(p=>p.id===id));if(!name)return alert('氏名を入力してください');if(!['会社管理者','現場管理者','担当者','閲覧者'].includes(role))return alert('役割を選択してください');if(role!=='会社管理者'&&!projectIds.length)return alert('所属現場を1つ以上選択してください');let old=data.users,oldActive=data.activeUserId,previous=old.find(u=>u.id===editingUserId),user={id:previous?.id||uid(),name,affiliation:String(f.get('affiliation')||'').trim(),email:String(f.get('email')||'').trim(),phone:String(f.get('phone')||'').trim(),role,projectIds,siteRoles:Object.fromEntries(projectIds.map(id=>[id,f.getAll(`siteRole:${id}`).map(String).filter(x=>['現場管理者','担当者','閲覧者'].includes(x))]).map(([id,roles])=>[id,roles.length?roles:[role==='会社管理者'?'現場管理者':role]]))};data.users=previous?old.map(u=>u.id===previous.id?user:u):[...old,user];if(!data.activeUserId)data.activeUserId=user.id;if(!save()){data.users=old;data.activeUserId=oldActive;return}}editingUserId='';closeForm();render()},true);


fields.partnerCompany={title:'協力業者を登録',html:`<label class="field">工種<input name="trade" list="partnerTradeList" required maxlength="80" placeholder="選択、または自由に入力"><datalist id="partnerTradeList">${PARTNER_TRADES.map(t=>`<option value="${esc(t)}"></option>`).join('')}</datalist></label><label class="field">会社名<input name="name" required maxlength="120"></label><label class="field">担当者<input name="contact" maxlength="80"></label><label class="field">電話番号<input type="tel" name="phone" maxlength="40"></label><label class="field">メールアドレス<input type="email" name="email" maxlength="120"></label><label class="field">備考<textarea name="note" maxlength="500"></textarea></label>`};
let editingPartnerId='',editingPartnerSiteId='';
function openPartnerForm(id='',trade=''){
  const site=data.projects.find(p=>p.id===projectId);if(!site)return;
  const partner=(site.subcontractors||[]).find(p=>p.id===id);
  editingPartnerId=partner?.id||'';editingPartnerSiteId=site.id;
  openForm('partnerCompany');
  $('#modalTitle').textContent=partner?'協力業者を編集':'協力業者を登録';
  for(const key of ['trade','name','contact','phone','email','note'])$('#entryForm [name='+key+']').value=partner?.[key]||(key==='trade'?trade:'');
}
document.addEventListener('toggle',e=>{
  const detail=e.target;if(!detail.matches?.('[data-hierarchy-section]'))return;
  const id=detail.dataset.hierarchySite,key=detail.dataset.hierarchySection;
  if(!data.projects.some(p=>p.id===id))return;
  const previous=data.hierarchySections||{};
  if(previous[id]?.[key]===detail.open)return;
  data.hierarchySections={...previous,[id]:{...previous[id],[key]:detail.open}};
  if(!save())data.hierarchySections=previous;
},true);
document.addEventListener('click',e=>{
  const button=e.target.closest('[data-partner-add],[data-partner-trade],[data-partner-edit],[data-partner-delete]');if(!button)return;
  if(button.hasAttribute('data-partner-add'))return openPartnerForm();
  if(button.hasAttribute('data-partner-trade'))return openPartnerForm('',button.dataset.partnerTrade);
  if(button.hasAttribute('data-partner-edit'))return openPartnerForm(button.dataset.partnerEdit);
  const site=data.projects.find(p=>p.id===projectId),partner=site?.subcontractors?.find(p=>p.id===button.dataset.partnerDelete);
  if(!partner||!confirm('「'+partner.name+'」の協力業者登録を削除しますか？'))return;
  const previous=site.subcontractors;site.subcontractors=previous.filter(p=>p.id!==partner.id);
  if(!save()){site.subcontractors=previous;return}render();
});
$('#entryForm').addEventListener('submit',e=>{
  if(formType!=='partnerCompany')return;e.preventDefault();e.stopImmediatePropagation();
  const site=data.projects.find(p=>p.id===editingPartnerSiteId);if(!site)return;
  const f=new FormData(e.currentTarget),values=Object.fromEntries(['trade','name','contact','phone','email','note'].map(k=>[k,String(f.get(k)||'').trim()]));
  if(!values.trade||!values.name){alert('工種と会社名を入力してください');return}
  const previous=site.subcontractors||[],old=previous.find(p=>p.id===editingPartnerId),partner={id:old?.id||uid(),...values};
  site.subcontractors=old?previous.map(p=>p.id===old.id?partner:p):[...previous,partner];
  if(!save()){site.subcontractors=previous;return}
  editingPartnerId='';editingPartnerSiteId='';closeForm();render();
},true);


function renderLaborDocuments(){return intro('SAFETY DOCUMENTS','労働基準監督署提出書類',data.projects.find(p=>p.id===projectId)?.name||'現場を選択してください')+"<style>.labor-docs{font-size:1rem;line-height:1.7}.labor-docs h2{font-size:1.15rem;margin:0 0 12px}.labor-docs .labor-section{margin-top:22px}.labor-docs details{border-top:1px solid #e1eaf0;padding:12px 0}.labor-docs summary{cursor:pointer;overflow-wrap:anywhere}.labor-docs summary strong{font-size:1rem}.labor-docs .labor-deadline{display:block;margin:4px 0 0 20px;color:#087c83;font-size:.875rem}.labor-docs dl{margin:14px 0 0;padding:14px;background:#f4f7fa;border-radius:8px}.labor-docs dt{font-weight:700;margin-top:12px}.labor-docs dt:first-child{margin-top:0}.labor-docs dd{margin:3px 0 0;overflow-wrap:anywhere}.labor-docs .labor-status{font-size:.875rem;color:#536d7e;display:inline-block;margin-left:8px}.labor-docs a{color:#087c83;text-decoration:underline;text-underline-offset:3px}.labor-docs p{margin:8px 0}.labor-docs .labor-note{font-size:.875rem}.labor-docs .labor-links{display:flex;flex-wrap:wrap;gap:12px}.labor-docs .btn{font-size:1rem}.labor-docs .labor-status-required{color:#9c590c}</style><div class=\"labor-docs\"><button type=\"button\" class=\"btn secondary\" data-go=\"safety\">安全書類に戻る</button><section class=\"card labor-section\"><h2>提出要否・期限の確認</h2><p>建設現場でよく使う主な届出・報告をまとめています。書類名を押すと、必要な条件・提出時期・不要の理由が開きます。</p><p>確認日：2026年10月1日。工種・規模・設備・労働者数を条件と照合してください。以下はこの現場の提出要否を確定した結果ではありません。</p><p class=\"labor-note\">人数は原則として各会社の事業場単位。元請・下請の合計人数で判定する統括管理の制度とは区別します。計画届の認定免除、特殊工事、個別指示は別途確認してください。</p></section><section class=\"card labor-section\"><h2>工事開始・計画・設備の届出</h2><details><summary><strong>特定元方事業者等の事業開始報告</strong><span class=\"labor-status labor-status-required\">条件に該当するとき必要</span><span class=\"labor-deadline\">作業開始後、遅滞なく。</span></summary><dl><dt>提出が必要な条件</dt><dd>元請と関係請負人の労働者が同じ場所で作業する建設工事など。</dd><dt>いつ提出するか</dt><dd>作業開始後、遅滞なく。</dd><dt>不要の場合・理由</dt><dd>対象の混在作業がない場合。この報告と労働保険の成立届は別の手続き。</dd><dt>提出者・提出先</dt><dd>元請等／現場所在地を管轄する監督署</dd><dt>確認事項</dt><dd>人数が少ないだけで提出不要にはなりません。</dd><dt>根拠・公式資料</dt><dd><a href=\"https://jsite.mhlw.go.jp/miyagi-roudoukyoku/2/213/21310.html\" target=\"_blank\" rel=\"noopener noreferrer\">厚生労働省・労働局の案内を確認</a></dd></dl></details><details><summary><strong>共同企業体代表者（変更）届</strong><span class=\"labor-status labor-status-required\">条件に該当するとき必要</span><span class=\"labor-deadline\">着工14日前まで。変更時は速やかに。</span></summary><dl><dt>提出が必要な条件</dt><dd>複数の建設業者が共同連帯して請け負い、JV代表者を選定・変更する場合。</dd><dt>いつ提出するか</dt><dd>着工14日前まで。変更時は速やかに。</dd><dt>不要の場合・理由</dt><dd>単独施工など、JVに該当しない場合。</dd><dt>提出者・提出先</dt><dd>JV代表者／所轄監督署を経由して労働局</dd><dt>根拠・公式資料</dt><dd><a href=\"https://jsite.mhlw.go.jp/miyagi-roudoukyoku/2/213/21310.html\" target=\"_blank\" rel=\"noopener noreferrer\">厚生労働省・労働局の案内を確認</a></dd></dl></details><details><summary><strong>建設工事計画届（様式第21号）</strong><span class=\"labor-status labor-status-required\">条件に該当するとき必要</span><span class=\"labor-deadline\">対象工事の開始14日前まで。</span></summary><dl><dt>提出が必要な条件</dt><dd>例：高さ31mを超える建築物等、深さ・高さ10m以上の対象地山掘削、対象の橋梁・ずい道・圧気工法など。</dd><dt>いつ提出するか</dt><dd>対象工事の開始14日前まで。</dd><dt>不要の場合・理由</dt><dd>安衛則第90条の対象工事に該当しない場合。高さや深さだけで全工種を判定しないこと。</dd><dt>提出者・提出先</dt><dd>仕事を行う事業者／現場の監督署</dd><dt>確認事項</dt><dd>計画図、工程、施工方法、安全対策等を添付。特に大規模な工事は別途30日前の大臣届を確認。</dd><dt>根拠・公式資料</dt><dd><a href=\"https://jsite.mhlw.go.jp/yamaguchi-roudoukyoku/content/contents/002207707.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">厚生労働省・労働局の案内を確認</a></dd></dl></details><details><summary><strong>大規模建設工事の計画届（大臣届）</strong><span class=\"labor-status labor-status-required\">条件に該当するとき必要</span><span class=\"labor-deadline\">仕事開始30日前まで。</span></summary><dl><dt>提出が必要な条件</dt><dd>安衛則第89条の2に該当する特に大規模な建設工事。</dd><dt>いつ提出するか</dt><dd>仕事開始30日前まで。</dd><dt>不要の場合・理由</dt><dd>同条の規模・工法等に該当しない場合。</dd><dt>提出者・提出先</dt><dd>仕事を行う事業者／厚生労働大臣宛て（所轄署・労働局と確認）</dd><dt>確認事項</dt><dd>通常の14日前の監督署届とは対象・提出先が異なります。</dd><dt>根拠・公式資料</dt><dd><a href=\"https://www.mhlw.go.jp/stf/seisakunitsuite/bunya/0000207439.html\" target=\"_blank\" rel=\"noopener noreferrer\">厚生労働省・労働局の案内を確認</a></dd></dl></details><details><summary><strong>機械等設置・移転・変更届：足場</strong><span class=\"labor-status labor-status-required\">条件に該当するとき必要</span><span class=\"labor-deadline\">設置等の工事開始30日前まで。</span></summary><dl><dt>提出が必要な条件</dt><dd>つり足場・張出し足場、または高さ10m以上のその他の足場。組立てから解体まで60日以上のもの。</dd><dt>いつ提出するか</dt><dd>設置等の工事開始30日前まで。</dd><dt>不要の場合・理由</dt><dd>設置期間60日未満、または対象種類・高さに該当しない場合。</dd><dt>提出者・提出先</dt><dd>設置等を行う事業者／現場の監督署</dd><dt>確認事項</dt><dd>届出不要でも、組立計画・点検・作業主任者等の必要な措置は残ります。</dd><dt>根拠・公式資料</dt><dd><a href=\"https://jsite.mhlw.go.jp/yamaguchi-roudoukyoku/content/contents/002207707.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">厚生労働省・労働局の案内を確認</a></dd></dl></details><details><summary><strong>機械等設置・移転・変更届：型枠支保工</strong><span class=\"labor-status labor-status-required\">条件に該当するとき必要</span><span class=\"labor-deadline\">設置等の工事開始30日前まで。</span></summary><dl><dt>提出が必要な条件</dt><dd>支柱の高さ3.5m以上の型枠支保工。</dd><dt>いつ提出するか</dt><dd>設置等の工事開始30日前まで。</dd><dt>不要の場合・理由</dt><dd>支柱の高さが3.5m未満の場合。この届には足場の60日未満の除外を流用しないこと。</dd><dt>提出者・提出先</dt><dd>設置等を行う事業者／現場の監督署</dd><dt>根拠・公式資料</dt><dd><a href=\"https://jsite.mhlw.go.jp/yamaguchi-roudoukyoku/content/contents/002207707.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">厚生労働省・労働局の案内を確認</a></dd></dl></details><details><summary><strong>機械等設置・移転・変更届：架設通路</strong><span class=\"labor-status labor-status-required\">条件に該当するとき必要</span><span class=\"labor-deadline\">設置等の工事開始30日前まで。</span></summary><dl><dt>提出が必要な条件</dt><dd>高さ・長さがともに10m以上で、組立てから解体まで60日以上の架設通路。</dd><dt>いつ提出するか</dt><dd>設置等の工事開始30日前まで。</dd><dt>不要の場合・理由</dt><dd>高さ・長さ・期間の対象条件を満たさない場合。</dd><dt>提出者・提出先</dt><dd>設置等を行う事業者／現場の監督署</dd><dt>根拠・公式資料</dt><dd><a href=\"https://jsite.mhlw.go.jp/yamaguchi-roudoukyoku/content/contents/002207707.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">厚生労働省・労働局の案内を確認</a></dd></dl></details><details><summary><strong>石綿除去等の建設工事計画届</strong><span class=\"labor-status labor-status-required\">条件に該当するとき必要</span><span class=\"labor-deadline\">対象作業の開始14日前まで。</span></summary><dl><dt>提出が必要な条件</dt><dd>対象の吹付石綿、石綿含有保温材・耐火被覆材等の除去、封じ込め、囲い込み。</dd><dt>いつ提出するか</dt><dd>対象作業の開始14日前まで。</dd><dt>不要の場合・理由</dt><dd>対象の石綿作業がない場合。一般の成形板等があるだけで、この届の対象とは限りません。</dd><dt>提出者・提出先</dt><dd>仕事を行う事業者／現場の監督署</dd><dt>確認事項</dt><dd>2021年に対象拡大。事前調査結果報告や自治体への届出は別途確認。</dd><dt>根拠・公式資料</dt><dd><a href=\"https://www.ishiwata.mhlw.go.jp/point/\" target=\"_blank\" rel=\"noopener noreferrer\">厚生労働省・労働局の案内を確認</a></dd></dl></details><details><summary><strong>石綿事前調査結果報告</strong><span class=\"labor-status labor-status-required\">条件に該当するとき必要</span><span class=\"labor-deadline\">事前調査を終え、対象工事の開始前に報告。</span></summary><dl><dt>提出が必要な条件</dt><dd>建築物解体80㎡以上、建築物改修の請負金額税込100万円以上、対象工作物の解体・改修税込100万円以上など。</dd><dt>いつ提出するか</dt><dd>事前調査を終え、対象工事の開始前に報告。</dd><dt>不要の場合・理由</dt><dd>報告の規模等に該当しない場合。石綿なしの結果でも対象規模なら報告が必要。</dd><dt>提出者・提出先</dt><dd>原則として元請／石綿事前調査結果報告システム</dd><dt>確認事項</dt><dd>報告不要でも事前調査・記録・掲示等が必要な場合があります。船舶の対象工事等は公式資料で確認。</dd><dt>根拠・公式資料</dt><dd><a href=\"https://www.ishiwata.mhlw.go.jp/result-reporting-system/\" target=\"_blank\" rel=\"noopener noreferrer\">厚生労働省・労働局の案内を確認</a></dd></dl></details><details><summary><strong>クレーン設置届・設置報告書</strong><span class=\"labor-status labor-status-required\">条件に該当するとき必要</span><span class=\"labor-deadline\">設置届は設置工事30日前、設置報告は設置前。</span></summary><dl><dt>提出が必要な条件</dt><dd>固定式クレーン：つり上げ荷重3t以上は設置届、0.5t以上3t未満は設置報告。スタッカー式は別基準。</dd><dt>いつ提出するか</dt><dd>設置届は設置工事30日前、設置報告は設置前。</dd><dt>不要の場合・理由</dt><dd>当該クレーンを設置しない場合、または当該届・報告の基準未満。</dd><dt>提出者・提出先</dt><dd>設置事業者／現場の監督署</dd><dt>確認事項</dt><dd>移動式クレーンの届・検査は別制度。機械の種類で確認。</dd><dt>根拠・公式資料</dt><dd><a href=\"https://www.mhlw.go.jp/web/t_doc?dataId=74020000\" target=\"_blank\" rel=\"noopener noreferrer\">厚生労働省・労働局の案内を確認</a></dd></dl></details><details><summary><strong>建設用リフト設置届・落成検査申請</strong><span class=\"labor-status labor-status-required\">条件に該当するとき必要</span><span class=\"labor-deadline\">設置届は設置工事開始30日前まで。使用前に必要な検査を受ける。</span></summary><dl><dt>提出が必要な条件</dt><dd>積載荷重0.25t以上、ガイドレール等の高さ10m以上の建設用リフトを設置する場合。</dd><dt>いつ提出するか</dt><dd>設置届は設置工事開始30日前まで。使用前に必要な検査を受ける。</dd><dt>不要の場合・理由</dt><dd>積載荷重0.25t未満、または高さ10m未満など適用除外に該当する場合。簡易リフト・エレベーターは別制度。</dd><dt>提出者・提出先</dt><dd>設置事業者／現場の監督署</dd><dt>根拠・公式資料</dt><dd><a href=\"https://www.mhlw.go.jp/web/t_doc?dataId=74020000\" target=\"_blank\" rel=\"noopener noreferrer\">厚生労働省・労働局の案内を確認</a></dd></dl></details><details><summary><strong>ゴンドラ設置届</strong><span class=\"labor-status labor-status-required\">条件に該当するとき必要</span><span class=\"labor-deadline\">設置する前。</span></summary><dl><dt>提出が必要な条件</dt><dd>法令上のゴンドラを設置する場合。</dd><dt>いつ提出するか</dt><dd>設置する前。</dd><dt>不要の場合・理由</dt><dd>対象のゴンドラを設置しない場合。</dd><dt>提出者・提出先</dt><dd>設置事業者／現場の監督署</dd><dt>根拠・公式資料</dt><dd><a href=\"https://jsite.mhlw.go.jp/miyagi-roudoukyoku/2/213/21310.html\" target=\"_blank\" rel=\"noopener noreferrer\">厚生労働省・労働局の案内を確認</a></dd></dl></details></section><section class=\"card labor-section\"><h2>会社・事業場の労務・管理体制</h2><details><summary><strong>適用事業報告</strong><span class=\"labor-status labor-status-required\">条件に該当するとき必要</span><span class=\"labor-deadline\">遅滞なく。</span></summary><dl><dt>提出が必要な条件</dt><dd>労働者を使用し、労働基準法の適用事業となった場合。</dd><dt>いつ提出するか</dt><dd>遅滞なく。</dd><dt>不要の場合・理由</dt><dd>既に報告済みの同一事業場で単に現場が増えた場合は、新たな事業場に当たるか確認。</dd><dt>提出者・提出先</dt><dd>使用者／事業場を管轄する監督署</dd><dt>根拠・公式資料</dt><dd><a href=\"https://jsite.mhlw.go.jp/kochi-roudoukyoku/hourei_seido_tetsuzuki/roudoukijun_keiyaku/hourei_seido/hourei02.html\" target=\"_blank\" rel=\"noopener noreferrer\">厚生労働省・労働局の案内を確認</a></dd></dl></details><details><summary><strong>労働保険 保険関係成立届</strong><span class=\"labor-status labor-status-required\">条件に該当するとき必要</span><span class=\"labor-deadline\">成立日から10日以内。</span></summary><dl><dt>提出が必要な条件</dt><dd>単独有期事業などで新たに保険関係が成立する場合。</dd><dt>いつ提出するか</dt><dd>成立日から10日以内。</dd><dt>不要の場合・理由</dt><dd>既存の一括有期事業に含まれる個々の工事など、別の保険関係が成立しない場合。</dd><dt>提出者・提出先</dt><dd>通常は元請の事業主／管轄監督署等</dd><dt>確認事項</dt><dd>一括有期事業の要件や下請分離の有無を確認。雇用保険の窓口はハローワーク。</dd><dt>根拠・公式資料</dt><dd><a href=\"https://jsite.mhlw.go.jp/hokkaido-roudoukyoku/newpage_00333.html\" target=\"_blank\" rel=\"noopener noreferrer\">厚生労働省・労働局の案内を確認</a></dd></dl></details><details><summary><strong>36協定届（時間外・休日労働に関する協定届）</strong><span class=\"labor-status labor-status-required\">条件に該当するとき必要</span><span class=\"labor-deadline\">対象の時間外・休日労働をさせる前。有効期間に合わせて更新。</span></summary><dl><dt>提出が必要な条件</dt><dd>法定労働時間を超える労働、または法定休日労働をさせる場合。</dd><dt>いつ提出するか</dt><dd>対象の時間外・休日労働をさせる前。有効期間に合わせて更新。</dd><dt>不要の場合・理由</dt><dd>法定時間外・法定休日労働をさせない場合。所定時間外と法定時間外は区別。</dd><dt>提出者・提出先</dt><dd>各雇用会社／事業場の監督署</dd><dt>確認事項</dt><dd>元請の協定が下請の労働者にそのまま適用されるわけではありません。</dd><dt>根拠・公式資料</dt><dd><a href=\"https://jsite.mhlw.go.jp/kochi-roudoukyoku/hourei_seido_tetsuzuki/roudoukijun_keiyaku/hourei_seido/hourei02.html\" target=\"_blank\" rel=\"noopener noreferrer\">厚生労働省・労働局の案内を確認</a></dd></dl></details><details><summary><strong>就業規則（変更）届</strong><span class=\"labor-status labor-status-required\">条件に該当するとき必要</span><span class=\"labor-deadline\">作成・変更後、遅滞なく。意見書を添付。</span></summary><dl><dt>提出が必要な条件</dt><dd>常時10人以上の労働者を使用する事業場で作成・変更した場合。</dd><dt>いつ提出するか</dt><dd>作成・変更後、遅滞なく。意見書を添付。</dd><dt>不要の場合・理由</dt><dd>常時10人未満では法定届出義務の対象外。会社全体や現場の全業者合計で数えない。</dd><dt>提出者・提出先</dt><dd>使用者／事業場の監督署</dd><dt>根拠・公式資料</dt><dd><a href=\"https://jsite.mhlw.go.jp/kochi-roudoukyoku/hourei_seido_tetsuzuki/roudoukijun_keiyaku/hourei_seido/hourei02.html\" target=\"_blank\" rel=\"noopener noreferrer\">厚生労働省・労働局の案内を確認</a></dd></dl></details><details><summary><strong>安全管理者・衛生管理者・産業医等の選任報告</strong><span class=\"labor-status labor-status-required\">条件に該当するとき必要</span><span class=\"labor-deadline\">事由発生14日以内に選任、選任後遅滞なく報告。</span></summary><dl><dt>提出が必要な条件</dt><dd>建設業の事業場では原則50人以上で安全管理者・衛生管理者・産業医、100人以上で総括安全衛生管理者が対象。</dd><dt>いつ提出するか</dt><dd>事由発生14日以内に選任、選任後遅滞なく報告。</dd><dt>不要の場合・理由</dt><dd>当該役職の業種・規模の選任義務に該当しない場合。</dd><dt>提出者・提出先</dt><dd>各事業者／事業場の監督署</dd><dt>確認事項</dt><dd>下請を含む統括安全衛生管理者の制度とは別。人数の集計単位を取り違えないこと。</dd><dt>根拠・公式資料</dt><dd><a href=\"https://jsite.mhlw.go.jp/tokyo-roudoukyoku/hourei_seido_tetsuzuki/anzen_eisei/a-kanri.html\" target=\"_blank\" rel=\"noopener noreferrer\">厚生労働省・労働局の案内を確認</a></dd></dl></details><details><summary><strong>建設業附属寄宿舎設置・移転・変更届／寄宿舎規則届</strong><span class=\"labor-status labor-status-required\">条件に該当するとき必要</span><span class=\"labor-deadline\">設置等は工事着手14日前まで。規則の作成・変更は遅滞なく。</span></summary><dl><dt>提出が必要な条件</dt><dd>法令上の事業附属寄宿舎を設ける・変更する場合。</dd><dt>いつ提出するか</dt><dd>設置等は工事着手14日前まで。規則の作成・変更は遅滞なく。</dd><dt>不要の場合・理由</dt><dd>対象寄宿舎がない場合。一般の宿泊施設の利用が該当するかは実態で判断。</dd><dt>提出者・提出先</dt><dd>使用者／管轄監督署</dd><dt>根拠・公式資料</dt><dd><a href=\"https://jsite.mhlw.go.jp/kochi-roudoukyoku/hourei_seido_tetsuzuki/roudoukijun_keiyaku/hourei_seido/hourei02.html\" target=\"_blank\" rel=\"noopener noreferrer\">厚生労働省・労働局の案内を確認</a></dd></dl></details></section><section class=\"card labor-section\"><h2>健康診断・災害・事故の報告</h2><details><summary><strong>定期健康診断結果報告</strong><span class=\"labor-status labor-status-required\">条件に該当するとき必要</span><span class=\"labor-deadline\">実施後、遅滞なく。</span></summary><dl><dt>提出が必要な条件</dt><dd>常時50人以上を使用する事業場で対象の定期健康診断を行った場合。</dd><dt>いつ提出するか</dt><dd>実施後、遅滞なく。</dd><dt>不要の場合・理由</dt><dd>常時50人未満はこの結果報告の義務対象外。健康診断自体の実施義務は別。</dd><dt>提出者・提出先</dt><dd>雇用事業者／事業場の監督署</dd><dt>確認事項</dt><dd>個人の健康診断書を全員分提出する手続きではありません。</dd><dt>根拠・公式資料</dt><dd><a href=\"https://www.mhlw.go.jp/stf/seisakunitsuite/bunya/koyou_roudou/roudoukijun/faq/newpage_50800.html\" target=\"_blank\" rel=\"noopener noreferrer\">厚生労働省・労働局の案内を確認</a></dd></dl></details><details><summary><strong>特殊健康診断・有害業務の歯科健康診断結果報告</strong><span class=\"labor-status labor-status-required\">条件に該当するとき必要</span><span class=\"labor-deadline\">対象の結果報告は実施後、遅滞なく。</span></summary><dl><dt>提出が必要な条件</dt><dd>有機溶剤・特定化学物質・石綿など、法令で対象となる業務の健診を実施した場合。</dd><dt>いつ提出するか</dt><dd>対象の結果報告は実施後、遅滞なく。</dd><dt>不要の場合・理由</dt><dd>対象業務・健診に該当しない場合。50人未満という理由だけでは不要にならない。</dd><dt>提出者・提出先</dt><dd>雇用事業者／管轄監督署</dd><dt>確認事項</dt><dd>健診の種類ごとの対象条件・頻度・報告様式を確認。</dd><dt>根拠・公式資料</dt><dd><a href=\"https://www.mhlw.go.jp/stf/seisakunitsuite/bunya/koyou_roudou/roudoukijun/faq/newpage_50800.html\" target=\"_blank\" rel=\"noopener noreferrer\">厚生労働省・労働局の案内を確認</a></dd></dl></details><details><summary><strong>じん肺健康管理実施状況報告</strong><span class=\"labor-status labor-status-required\">条件に該当するとき必要</span><span class=\"labor-deadline\">12月31日時点の状況を翌年2月末まで。</span></summary><dl><dt>提出が必要な条件</dt><dd>粉じん作業の対象労働者について、じん肺健康管理の報告義務に該当する場合。</dd><dt>いつ提出するか</dt><dd>12月31日時点の状況を翌年2月末まで。</dd><dt>不要の場合・理由</dt><dd>粉じん作業等の報告対象に該当しない場合。</dd><dt>提出者・提出先</dt><dd>事業者／管轄監督署</dd><dt>根拠・公式資料</dt><dd><a href=\"https://www.mhlw.go.jp/stf/seisakunitsuite/bunya/koyou_roudou/roudoukijun/faq/newpage_50800.html\" target=\"_blank\" rel=\"noopener noreferrer\">厚生労働省・労働局の案内を確認</a></dd></dl></details><details><summary><strong>ストレスチェック実施結果等報告</strong><span class=\"labor-status labor-status-required\">条件に該当するとき必要</span><span class=\"labor-deadline\">1年以内ごとに1回、定期に報告。</span></summary><dl><dt>提出が必要な条件</dt><dd>常時50人以上の労働者を使用する事業場。</dd><dt>いつ提出するか</dt><dd>1年以内ごとに1回、定期に報告。</dd><dt>不要の場合・理由</dt><dd>2026年10月時点で50人未満はこの報告の義務対象外。</dd><dt>提出者・提出先</dt><dd>事業者／事業場の監督署</dd><dt>確認事項</dt><dd>50人未満への実施義務拡大は2028年4月1日。実施義務と報告義務は分けて確認。</dd><dt>根拠・公式資料</dt><dd><a href=\"https://www.mhlw.go.jp/web/t_doc?dataId=00tc1013&amp;dataType=1&amp;pageNo=1\" target=\"_blank\" rel=\"noopener noreferrer\">厚生労働省・労働局の案内を確認</a></dd></dl></details><details><summary><strong>労働者死傷病報告：死亡・休業4日以上</strong><span class=\"labor-status labor-status-required\">条件に該当するとき必要</span><span class=\"labor-deadline\">遅滞なく報告。</span></summary><dl><dt>提出が必要な条件</dt><dd>労災等で労働者が死亡、または休業4日以上（見込みを含む）。</dd><dt>いつ提出するか</dt><dd>遅滞なく報告。</dd><dt>不要の場合・理由</dt><dd>休業1〜3日は別の報告。通常の通勤災害・不休災害はこの報告の対象外。</dd><dt>提出者・提出先</dt><dd>被災者の雇用事業者／災害発生場所の監督署</dd><dt>確認事項</dt><dd>労災保険給付の請求とは別。2025年から原則電子申請。</dd><dt>根拠・公式資料</dt><dd><a href=\"https://jsite.mhlw.go.jp/akita-roudoukyoku/newpage_02300.html\" target=\"_blank\" rel=\"noopener noreferrer\">厚生労働省・労働局の案内を確認</a></dd></dl></details><details><summary><strong>労働者死傷病報告：休業1〜3日</strong><span class=\"labor-status labor-status-required\">条件に該当するとき必要</span><span class=\"labor-deadline\">四半期ごとに、翌月末まで（4/30・7/31・10/31・翌1/31）。</span></summary><dl><dt>提出が必要な条件</dt><dd>労災等で労働者が休業1〜3日した場合。</dd><dt>いつ提出するか</dt><dd>四半期ごとに、翌月末まで（4/30・7/31・10/31・翌1/31）。</dd><dt>不要の場合・理由</dt><dd>休業なしの不休災害・通常の通勤災害は対象外。4日以上は遅滞なく別報告。</dd><dt>提出者・提出先</dt><dd>被災者の雇用事業者／災害発生場所の監督署</dd><dt>確認事項</dt><dd>軽傷でも休業があれば対象。2025年から原則電子申請。</dd><dt>根拠・公式資料</dt><dd><a href=\"https://jsite.mhlw.go.jp/akita-roudoukyoku/newpage_02300.html\" target=\"_blank\" rel=\"noopener noreferrer\">厚生労働省・労働局の案内を確認</a></dd></dl></details><details><summary><strong>事故報告（安衛則第96条）</strong><span class=\"labor-status labor-status-required\">条件に該当するとき必要</span><span class=\"labor-deadline\">発生後、遅滞なく。</span></summary><dl><dt>提出が必要な条件</dt><dd>火災・爆発、対象のクレーン倒壊など、同条に定める事故。</dd><dt>いつ提出するか</dt><dd>発生後、遅滞なく。</dd><dt>不要の場合・理由</dt><dd>同条の事故に該当しない場合。けが人がいないという理由だけでは不要にならない。</dd><dt>提出者・提出先</dt><dd>事業者／事故発生場所の監督署</dd><dt>確認事項</dt><dd>死傷病報告と別に要否を確認。</dd><dt>根拠・公式資料</dt><dd><a href=\"https://www.mhlw.go.jp/web/t_doc?dataId=74003000&amp;dataType=0\" target=\"_blank\" rel=\"noopener noreferrer\">厚生労働省・労働局の案内を確認</a></dd></dl></details><details><summary><strong>労災保険給付の請求書</strong><span class=\"labor-status labor-status-required\">条件に該当するとき必要</span><span class=\"labor-deadline\">給付を請求するとき。給付別の時効に注意。</span></summary><dl><dt>提出が必要な条件</dt><dd>被災者等が療養・休業等の給付を請求する場合。</dd><dt>いつ提出するか</dt><dd>給付を請求するとき。給付別の時効に注意。</dd><dt>不要の場合・理由</dt><dd>対象給付を請求しない場合でも、死傷病報告の義務は別に残る。</dd><dt>提出者・提出先</dt><dd>被災者等／監督署。様式5号等は指定医療機関経由</dd><dt>確認事項</dt><dd>通勤災害・不休災害も給付対象になる場合があります。業務災害の休業給付は原則4日目から。</dd><dt>根拠・公式資料</dt><dd><a href=\"https://www.mhlw.go.jp/stf/seisakunitsuite/bunya/koyou_roudou/roudoukijun/zigyonushi/rousai/index.html\" target=\"_blank\" rel=\"noopener noreferrer\">厚生労働省・労働局の案内を確認</a></dd></dl></details></section><section class=\"card labor-section\"><h2>通常は労基署への定期提出が不要な書類</h2><p>提出不要でも、作成・保管・元請への提出等が必要な場合があります。監督署の調査・指示で提出を求められた場合は、その内容と期限に従ってください。</p><details><summary><strong>施工体制台帳</strong><span class=\"labor-status\">通常の定期提出は不要</span></summary><dl><dt>不要の理由・通常の扱い</dt><dd>建設業法等による施工体制の記録。労基署への定期提出書類ではなく、作成・現場備置きや発注者への提出等を確認。</dd><dt>作成・確認する時期</dt><dd>工事開始・下請契約や体制変更に合わせて作成・更新。</dd><dt>関連する公式資料</dt><dd><a href=\"https://www.mlit.go.jp/totikensangyo/const/1_6_bt_000191.html\" target=\"_blank\" rel=\"noopener noreferrer\">関連制度を確認</a></dd></dl></details><details><summary><strong>施工体制配置図</strong><span class=\"labor-status\">通常の定期提出は不要</span></summary><dl><dt>不要の理由・通常の扱い</dt><dd>施工体系図や現場の体制・配置を示す資料として管理。通常は元請・発注者向けで、労基署への定期提出書類ではありません。</dd><dt>作成・確認する時期</dt><dd>着工時、体制・配置変更時。</dd><dt>関連する公式資料</dt><dd><a href=\"https://www.mlit.go.jp/totikensangyo/const/1_6_bt_000191.html\" target=\"_blank\" rel=\"noopener noreferrer\">関連制度を確認</a></dd></dl></details><details><summary><strong>再下請通知書</strong><span class=\"labor-status\">通常の定期提出は不要</span></summary><dl><dt>不要の理由・通常の扱い</dt><dd>施工体制台帳を作成する元請等へ提出する資料。通常の提出先は労基署ではありません。</dd><dt>作成・確認する時期</dt><dd>再下請契約時・記載事項変更時。</dd><dt>関連する公式資料</dt><dd><a href=\"https://www.mlit.go.jp/totikensangyo/const/1_6_bt_000191.html\" target=\"_blank\" rel=\"noopener noreferrer\">関連制度を確認</a></dd></dl></details><details><summary><strong>会社情報・保険加入状況</strong><span class=\"labor-status\">通常の定期提出は不要</span></summary><dl><dt>不要の理由・通常の扱い</dt><dd>通常は元請の入場・下請審査資料。保険の加入届や労働保険成立届などの行政手続きは別です。</dd><dt>作成・確認する時期</dt><dd>契約・入場前、情報変更時。</dd><dt>関連する公式資料</dt><dd><a href=\"https://jsite.mhlw.go.jp/hokkaido-roudoukyoku/newpage_00333.html\" target=\"_blank\" rel=\"noopener noreferrer\">関連制度を確認</a></dd></dl></details><details><summary><strong>作業員名簿</strong><span class=\"labor-status\">通常の定期提出は不要</span></summary><dl><dt>不要の理由・通常の扱い</dt><dd>通常は元請へ提出・現場管理に使用。会社で作る労働者名簿も原則事業場で備える書類です。</dd><dt>作成・確認する時期</dt><dd>入場前、作業員の追加・変更時。</dd><dt>関連する公式資料</dt><dd><a href=\"https://www.mlit.go.jp/totikensangyo/const/1_6_bt_000191.html\" target=\"_blank\" rel=\"noopener noreferrer\">関連制度を確認</a></dd></dl></details><details><summary><strong>資格・免許証</strong><span class=\"labor-status\">通常の定期提出は不要</span></summary><dl><dt>不要の理由・通常の扱い</dt><dd>資格確認のため元請に提示・写しを提出。労基署へ全員分を定期提出するものではありません。選任届等の添付が必要な場合は別。</dd><dt>作成・確認する時期</dt><dd>入場・対象作業への配置前、更新時。</dd><dt>関連する公式資料</dt><dd><a href=\"https://www.mhlw.go.jp/stf/seisakunitsuite/bunya/koyou_roudou/roudoukijun/anzen/anzeneisei36/index.html\" target=\"_blank\" rel=\"noopener noreferrer\">関連制度を確認</a></dd></dl></details><details><summary><strong>新規入場者教育実施報告書</strong><span class=\"labor-status\">通常の定期提出は不要</span></summary><dl><dt>不要の理由・通常の扱い</dt><dd>通常は元請・現場で実施を記録。労働局が指定した事業場の安全衛生教育実施結果報告等とは別です。</dd><dt>作成・確認する時期</dt><dd>入場前・初回入場時の教育後。</dd><dt>関連する公式資料</dt><dd><a href=\"https://jsite.mhlw.go.jp/miyagi-roudoukyoku/2/213/21310.html\" target=\"_blank\" rel=\"noopener noreferrer\">関連制度を確認</a></dd></dl></details><details><summary><strong>健康診断書（個人）</strong><span class=\"labor-status\">通常の定期提出は不要</span></summary><dl><dt>不要の理由・通常の扱い</dt><dd>通常は雇用会社で健康管理し、必要な範囲で現場の就業適性を確認。個人票全員分の定期提出ではなく、対象事業場は結果報告を別途提出。</dd><dt>作成・確認する時期</dt><dd>入場・配置前の確認、健診実施後。</dd><dt>関連する公式資料</dt><dd><a href=\"https://www.mhlw.go.jp/stf/seisakunitsuite/bunya/koyou_roudou/roudoukijun/faq/newpage_50800.html\" target=\"_blank\" rel=\"noopener noreferrer\">関連制度を確認</a></dd></dl></details><details><summary><strong>安全請負調書・下請法／安全衛生契約書</strong><span class=\"labor-status\">通常の定期提出は不要</span></summary><dl><dt>不要の理由・通常の扱い</dt><dd>通常は元請・下請間の確認・契約資料。統一された名称の労基署届出ではないため、契約内容と指定提出先で管理。</dd><dt>作成・確認する時期</dt><dd>契約・着工前、内容変更時。</dd><dt>関連する公式資料</dt><dd><a href=\"https://www.mhlw.go.jp/stf/seisakunitsuite/bunya/koyou_roudou/roudoukijun/anzen/anzeneisei36/index.html\" target=\"_blank\" rel=\"noopener noreferrer\">関連制度を確認</a></dd></dl></details><details><summary><strong>作業計画書・施工要領書</strong><span class=\"labor-status\">通常の定期提出は不要</span></summary><dl><dt>不要の理由・通常の扱い</dt><dd>通常は事前に作成し現場で周知・保管。建設工事計画届・機械等設置届の添付資料になる場合は、その届出と一緒に提出。</dd><dt>作成・確認する時期</dt><dd>作業開始前、工法・設備等の変更前。</dd><dt>関連する公式資料</dt><dd><a href=\"https://jsite.mhlw.go.jp/yamaguchi-roudoukyoku/content/contents/002207707.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">関連制度を確認</a></dd></dl></details><details><summary><strong>SDS（安全データシート）</strong><span class=\"labor-status\">通常の定期提出は不要</span></summary><dl><dt>不要の理由・通常の扱い</dt><dd>供給者から受領し、化学物質管理・リスクアセスメント・労働者への周知に使用。通常はSDS自体の定期提出はありません。</dd><dt>作成・確認する時期</dt><dd>材料採用・使用開始前、改訂時。</dd><dt>関連する公式資料</dt><dd><a href=\"https://www.mhlw.go.jp/stf/newpage_11237.html\" target=\"_blank\" rel=\"noopener noreferrer\">関連制度を確認</a></dd></dl></details><details><summary><strong>危険予知KY</strong><span class=\"labor-status\">通常の定期提出は不要</span></summary><dl><dt>不要の理由・通常の扱い</dt><dd>現場で危険と対策を共有する活動記録。通常の定期提出書類ではなく、現場・会社のルールに従い実施・保管。</dd><dt>作成・確認する時期</dt><dd>日々の作業前、作業条件変更時。</dd><dt>関連する公式資料</dt><dd><a href=\"https://www.mhlw.go.jp/stf/newpage_11389.html\" target=\"_blank\" rel=\"noopener noreferrer\">関連制度を確認</a></dd></dl></details><details><summary><strong>一括有期事業開始届</strong><span class=\"labor-status\">廃止・提出不要</span></summary><dl><dt>不要の理由・通常の扱い</dt><dd>2019年4月1日以降に開始する対象工事については廃止により提出不要。成立届や年度更新等は別途必要です。</dd><dt>作成・確認する時期</dt><dd>廃止済みのため提出時期なし。</dd><dt>関連する公式資料</dt><dd><a href=\"https://jsite.mhlw.go.jp/fukui-roudoukyoku/news_topics/houdou/_120779/_120792_00005.html\" target=\"_blank\" rel=\"noopener noreferrer\">関連制度を確認</a></dd></dl></details></section><section class=\"card labor-section\"><h2>提出方法・対象外の手続き</h2><p>死傷病報告、選任報告、定期健診結果などは2025年から原則電子申請。電子申請が困難な場合の経過措置や、健診別の取扱いは公式案内で確認してください。</p><p>石綿の事前調査結果報告は専用システムを利用。大気汚染防止法の自治体届出や、発注者への安全書類提出とは別の手続きです。</p><p>ボイラー・圧力容器・移動式クレーン等の検査、機械の変更・休廃止、特殊工事・指定事業場の報告など、この一覧以外の手続きも対象設備・作業に応じて確認してください。</p><div class=\"labor-links\"><a href=\"https://www.mhlw.go.jp/stf/seisakunitsuite/bunya/koyou_roudou/roudoukijun/anzen/anzeneisei36/index.html\" target=\"_blank\" rel=\"noopener noreferrer\">安全衛生の公式様式</a><a href=\"https://jsite.mhlw.go.jp/kochi-roudoukyoku/hourei_seido_tetsuzuki/roudoukijun_keiyaku/hourei_seido/hourei02.html\" target=\"_blank\" rel=\"noopener noreferrer\">労務関係の届出案内</a><a href=\"https://www.ishiwata.mhlw.go.jp/result-reporting-system/\" target=\"_blank\" rel=\"noopener noreferrer\">石綿報告システムの案内</a></div></section></div>";}

// Change only the visible date window; existing tasks and lines keep their dates.
document.addEventListener('click',e=>{if(!e.target.closest('[data-schedule-today-start]'))return;const settings=scheduleSettings();settings.todayStart=!settings.todayStart;settings.start=settings.todayStart?today():settings.start.slice(0,7)+'-01';save();render()});
